cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>

const float SQRT_2_OVER_PI = 0.7978845608028654f;

__global__ void layer_norm_kernel(
    const float * __restrict__ x,
    const float * __restrict__ gamma,
    const float * __restrict__ beta,
    float * __restrict__ y,
    int B,
    int T,
    int C,
    float eps
) {
    int b_idx = blockIdx.x;
    int t_idx = blockIdx.y;
    if (b_idx >= B || t_idx >= T) return;

    int tid = threadIdx.x;
    int blk_sz = blockDim.x;
    extern __shared__ float shared_mem[];
    float *sum_x_shared = shared_mem;
    float *sum_xx_shared = shared_mem + blk_sz;

    float sum_x_local = 0.0f;
    float sum_xx_local = 0.0f;
    int offset_base = b_idx * T * C + t_idx * C;
    for (int j = tid; j < C; j += blk_sz) {
        float val = x[offset_base + j];
        sum_x_local += val;
        sum_xx_local += val * val;
    }

    sum_x_shared[tid] = sum_x_local;
    sum_xx_shared[tid] = sum_xx_local;
    __syncthreads();

    for (int s = blk_sz / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sum_x_shared[tid] += sum_x_shared[tid + s];
            sum_xx_shared[tid] += sum_xx_shared[tid + s];
        }
        __syncthreads();
    }

    float mean = sum_x_shared[0] / static_cast<float>(C);
    float xx_mean = sum_xx_shared[0] / static_cast<float>(C);
    float var = xx_mean - mean * mean;
    float scale = rsqrtf(fmaxf(var + eps, 1e-6f));

    for (int j = tid; j < C; j += blk_sz) {
        int idx = offset_base + j;
        float val = x[idx];
        val = (val - mean) * scale;
        y[idx] = val * gamma[j] + beta[j];
    }
}

__global__ void new_gelu_kernel(const float *input, float *output, int64_t N) {
    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx < N) {
        float x = input[idx];
        float x3 = x * x * x;
        float tanh_arg = SQRT_2_OVER_PI * (x + 0.044715f * x3);
        float tanh_out = tanhf(tanh_arg);
        output[idx] = 0.5f * x * (1.0f + tanh_out);
    }
}

torch::Tensor layer_norm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps = 1e-5f) {
    torch::Tensor out = torch::empty_like(x);
    int64_t B = x.size(0);
    int64_t seq_len = x.size(1);
    int64_t feat = x.size(2);
    const int threads = 256;
    dim3 grid(B, seq_len);
    dim3 block(threads);
    size_t smem = 2 * threads * sizeof(float);
    hipLaunchKernelGGL((layer_norm_kernel), dim3(grid), dim3(block), smem, 0, x.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), out.data_ptr<float>(), B, seq_len, feat, eps);
    return out;
}

torch::Tensor new_gelu_hip(torch::Tensor input) {
    torch::Tensor output = torch::empty_like(input);
    int64_t N = input.numel();
    const int block_size = 256;
    dim3 grid((N + block_size - 1) / block_size);
    dim3 threads(block_size);
    hipLaunchKernelGGL((new_gelu_kernel), dim3(grid), dim3(threads), 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), N);
    return output;
}
"""

custom_ops = load_inline(
    name="gpt_block",
    cpp_sources=[cpp_source],
    functions=["layer_norm_hip", "new_gelu_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    """ an unassuming Transformer block with custom kernels """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        self.custom_ops = custom_ops

    def mlpf(self, x):
        fc_out = self.mlp.c_fc(x)
        gelu_out = self.custom_ops.new_gelu_hip(fc_out)
        proj_out = self.mlp.c_proj(gelu_out)
        return self.mlp.dropout(proj_out)

    def forward(self, x):
        x1 = self.custom_ops.layer_norm_hip(x, self.ln_1.weight, self.ln_1.bias)
        x = x + self.attn(x1)
        x2 = self.custom_ops.layer_norm_hip(x, self.ln_2.weight, self.ln_2.bias)
        x = x + self.mlpf(x2)
        return x

