    for (int j = tid; j < (int)C; j += blk_sz) {
        float val = x[offset_base + j];
        sum_x_local += val;
        sum_xx_local += val * val;
    }

    sum_x_shared[tid] = sum_x_local;
    sum_xx_shared[tid] = sum_xx_local;
